import React, { createContext, useContext, useState, useEffect } from 'react';

interface AppSettings {
    currency: string;
    decimals: number;
    dateFormat: string;
}

interface SettingsContextType {
    settings: AppSettings;
    updateSettings: (newSettings: Partial<AppSettings>) => void;
    formatCurrency: (amount: number) => string;
    formatDate: (date: string | Date | undefined) => string;
}

const defaultSettings: AppSettings = {
    currency: '$',
    decimals: 2,
    dateFormat: 'dd/MM/yyyy'
};

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export const SettingsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [settings, setSettings] = useState<AppSettings>(() => {
        const saved = localStorage.getItem('appSettings');
        return saved ? JSON.parse(saved) : defaultSettings;
    });

    useEffect(() => {
        localStorage.setItem('appSettings', JSON.stringify(settings));
    }, [settings]);

    const updateSettings = (newSettings: Partial<AppSettings>) => {
        setSettings(prev => ({ ...prev, ...newSettings }));
    };

    const formatCurrency = (amount: number) => {
        if (amount === undefined || amount === null) return settings.currency + '0.00';
        return settings.currency + Number(amount).toFixed(settings.decimals);
    };

    const formatDate = (date: string | Date | undefined) => {
        if (!date) return '';
        const d = new Date(date);
        if (isNaN(d.getTime())) return '';

        const day = String(d.getDate()).padStart(2, '0');
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const year = d.getFullYear();

        if (settings.dateFormat === 'MM/dd/yyyy') return `${month}/${day}/${year}`;
        if (settings.dateFormat === 'yyyy-MM-dd') return `${year}-${month}-${day}`;
        return `${day}/${month}/${year}`; // Default dd/MM/yyyy
    };

    return (
        <SettingsContext.Provider value={{ settings, updateSettings, formatCurrency, formatDate }}>
            {children}
        </SettingsContext.Provider>
    );
};

export const useSettings = () => {
    const context = useContext(SettingsContext);
    if (!context) {
        throw new Error('useSettings must be used within a SettingsProvider');
    }
    return context;
};

import React, { useState } from 'react';
import { Save, UserPlus, Trash2 } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../services/db';
import { useLiveQuery } from 'dexie-react-hooks';
import { useNotification } from '../contexts/NotificationContext';
import { generateBackupData, restoreBackupData } from '../services/backupService';

interface BusinessDetails {
    name: string;
    address: string;
    phone: string;
    email: string;
    gstin: string;
    logoUrl?: string;
    country?: string;
    taxName?: string; // e.g. 'VAT', 'GST'
    vatNo?: string;
    crNo?: string;
}

const BusinessProfile: React.FC = () => {
    const { isAdmin, user } = useAuth();
    const { addToast } = useNotification();
    const [details, setDetails] = useState<BusinessDetails>(() => {
        const saved = localStorage.getItem('businessDetails');
        return saved ? JSON.parse(saved) : {
            name: '', address: '', phone: '', email: '', gstin: '',
        };
    });

    // User Management State
    const [newUser, setNewUser] = useState({ username: '', password: '', name: '', canBackup: false });
    const users = useLiveQuery(() => db.users.where('role').equals('shopkeeper').toArray(), []);
    const currentUser = useLiveQuery(() => user?.id ? db.users.get(user.id) : undefined, [user?.id]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setDetails({ ...details, [e.target.name]: e.target.value });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        localStorage.setItem('businessDetails', JSON.stringify(details));
        addToast('Details Saved Successfully', 'success');
    };

    const handleAddUser = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await db.users.add({
                username: newUser.username,
                password: newUser.password,
                name: newUser.name,
                role: 'shopkeeper',
                canBackup: newUser.canBackup
            });
            setNewUser({ username: '', password: '', name: '', canBackup: false });
            addToast('Shopkeeper Added Successfully', 'success');
        } catch {
            addToast('Error adding user. Username might be taken.', 'error');
        }
    };

    const handleDeleteUser = async (id: number) => {
        if (window.confirm('Are you sure you want to remove this user?')) {
            await db.users.delete(id);
            addToast('User removed successfully', 'success');
        }
    };

    const handleBackup = async () => {
        try {
            const data = await generateBackupData();
            const electron = (window as any).electron;

            if (electron) {
                const success = await electron.saveBackup(data);
                if (success) {
                    addToast('Backup saved to Documents folder!', 'success');
                } else {
                    addToast('Failed to save backup', 'error');
                }
            } else {
                // Browser Fallback
                const blob = new Blob([data], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `billing-backup-${new Date().toISOString().split('T')[0]}.json`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
                addToast('Backup downloaded successfully', 'success');
            }
        } catch (error) {
            console.error(error);
            addToast('Backup failed', 'error');
        }
    };

    const handleRestore = async () => {
        if (!isAdmin) return;
        if (!window.confirm('WARNING: This will overwrite ALL current data with the backup. Use with caution!')) return;

        try {
            const electron = (window as any).electron;

            const processRestore = async (content: string) => {
                try {
                    await restoreBackupData(content);
                    addToast('Data Restored Successfully. Reloading...', 'success');
                    setTimeout(() => window.location.reload(), 2000);
                } catch {
                    addToast('Restore failed: Invalid data or file', 'error');
                }
            };

            if (electron) {
                const content = await electron.readBackup();
                if (content) {
                    await processRestore(content);
                }
            } else {
                // Browser Fallback
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = '.json';
                input.onchange = (e) => {
                    const file = (e.target as HTMLInputElement).files?.[0];
                    if (file) {
                        const reader = new FileReader();
                        reader.onload = (e) => {
                            const result = e.target?.result as string;
                            if (result) processRestore(result);
                        };
                        reader.readAsText(file);
                    }
                };
                input.click();
            }

        } catch (error) {
            console.error(error);
            addToast('Restore initiation failed', 'error');
        }
    };

    const showBackupControls = isAdmin || currentUser?.canBackup;

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                // Basic size check (approx 500KB limit to avoid LS bloat)
                if (base64String.length > 700000) {
                    addToast('Logo file is too large! Please use a smaller image.', 'error');
                    return;
                }
                setDetails(prev => ({ ...prev, logoUrl: base64String }));
            };
            reader.readAsDataURL(file);
        }
    };

    return (
        <div className="p-6 max-w-4xl mx-auto space-y-8 pb-20">
            <h1 className="text-2xl font-bold text-slate-800 dark:text-white">Settings</h1>

            {/* Business Profile Section */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
                <h2 className="text-lg font-semibold mb-4 dark:text-white">Business Profile</h2>
                <form onSubmit={handleSubmit} className="space-y-4">

                    {/* Logo Upload */}
                    <div className="flex items-center gap-4 mb-4">
                        <div className="w-20 h-20 rounded-lg border border-slate-300 dark:border-slate-600 flex items-center justify-center overflow-hidden bg-slate-50 dark:bg-slate-900">
                            {details.logoUrl ? (
                                <img src={details.logoUrl} alt="Logo" className="w-full h-full object-contain" />
                            ) : (
                                <span className="text-xs text-slate-400">No Logo</span>
                            )}
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Shop Logo</label>
                            <input
                                type="file"
                                accept="image/*"
                                onChange={handleLogoUpload}
                                className="text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Business Name</label>
                            <input
                                type="text"
                                name="name"
                                value={details.name}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                            <input
                                type="text"
                                name="phone"
                                value={details.phone}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                            />
                        </div>
                        <div className="md:col-span-2">
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Address</label>
                            <textarea
                                name="address"
                                value={details.address}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                rows={2}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Country</label>
                            <select
                                name="country"
                                value={details.country || 'India'}
                                onChange={(e) => setDetails({ ...details, country: e.target.value })}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-900 dark:text-white"
                            >
                                <option value="India">India</option>
                                <option value="Saudi Arabia">Saudi Arabia (KSA)</option>
                                <option value="UAE">United Arab Emirates (UAE)</option>
                                <option value="USA">United States</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tax Name (e.g. VAT/GST)</label>
                            <input
                                type="text"
                                name="taxName"
                                value={details.taxName || ''}
                                placeholder="VAT"
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tax Registration No (VAT/GSTIN)</label>
                            <input
                                type="text"
                                name="gstin" // Keeping internal name as 'gstin' for simplified ID mapping, but labeled as Tax Registration
                                value={details.gstin}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Commercial Reg. No (CR)</label>
                            <input
                                type="text"
                                name="crNo"
                                value={details.crNo || ''}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                            <input
                                type="email"
                                name="email"
                                value={details.email}
                                onChange={handleChange}
                                className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                            />
                        </div>
                    </div>
                    <button
                        type="submit"
                        className="flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-semibold transition-colors"
                    >
                        <Save size={18} /> Save Details
                    </button>
                </form>
            </div>

            {/* Data Management Section */}
            {showBackupControls && (
                <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
                    <h2 className="text-lg font-semibold mb-4 dark:text-white">Data Management</h2>
                    <p className="text-sm text-slate-500 mb-4">
                        Securely backup your database to your Documents folder.
                        {isAdmin && " You can also restore data from a previous backup."}
                    </p>

                    <div className="flex flex-wrap gap-4">
                        <button
                            onClick={handleBackup}
                            className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
                        >
                            <Save size={18} /> Backup Data Now
                        </button>

                        {isAdmin && (
                            <button
                                onClick={handleRestore}
                                className="bg-orange-600 hover:bg-orange-700 text-white px-6 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
                            >
                                <UserPlus size={18} /> Import Data (Restore)
                            </button>
                        )}
                    </div>
                </div>
            )}

            {/* User Management Section (Admin Only) */}
            {isAdmin && (
                <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
                    <h2 className="text-lg font-semibold mb-4 dark:text-white flex items-center gap-2">
                        <UserPlus size={20} /> User Management
                    </h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {/* Add User Form */}
                        <form onSubmit={handleAddUser} className="space-y-4">
                            <h3 className="text-sm font-medium text-slate-500 uppercase">Add New Shopkeeper</h3>
                            <div>
                                <input
                                    type="text"
                                    placeholder="Full Name"
                                    value={newUser.name}
                                    onChange={e => setNewUser({ ...newUser, name: e.target.value })}
                                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                    required
                                />
                            </div>
                            <div>
                                <input
                                    type="text"
                                    placeholder="Username"
                                    value={newUser.username}
                                    onChange={e => setNewUser({ ...newUser, username: e.target.value })}
                                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                    required
                                />
                            </div>
                            <div>
                                <input
                                    type="password"
                                    placeholder="Password"
                                    value={newUser.password}
                                    onChange={e => setNewUser({ ...newUser, password: e.target.value })}
                                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                    required
                                />
                            </div>
                            <div className="flex items-center gap-2">
                                <input
                                    type="checkbox"
                                    id="canBackup"
                                    checked={newUser.canBackup}
                                    onChange={e => setNewUser({ ...newUser, canBackup: e.target.checked })}
                                    className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                                />
                                <label htmlFor="canBackup" className="text-sm text-slate-700 dark:text-slate-300 select-none">
                                    Allow this user to Backup Data?
                                </label>
                            </div>
                            <button
                                type="submit"
                                className="w-full bg-slate-900 dark:bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded-lg font-medium"
                            >
                                Create Account
                            </button>
                        </form>

                        {/* User List */}
                        <div>
                            <h3 className="text-sm font-medium text-slate-500 uppercase mb-3">Existing Shopkeepers</h3>
                            <div className="space-y-2">
                                {users?.map(user => (
                                    <div key={user.id} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-900 rounded-lg">
                                        <div>
                                            <p className="font-medium dark:text-white">{user.name}</p>
                                            <div className="text-xs text-slate-500 flex flex-col gap-1">
                                                <span>Username: <strong>{user.username}</strong></span>
                                                <span className={user.canBackup ? "text-green-600" : "text-slate-400"}>
                                                    Backup Access: {user.canBackup ? "Enabled" : "Disabled"}
                                                </span>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => handleDeleteUser(user.id!)}
                                            className="text-red-500 hover:bg-red-50 p-2 rounded-md transition-colors"
                                            title="Remove User"
                                        >
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                ))}
                                {users?.length === 0 && (
                                    <p className="text-slate-400 text-sm italic">No shopkeepers added yet.</p>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Change Admin Password Section */}
                    <div className="mt-8 border-t border-slate-200 dark:border-slate-700 pt-6">
                        <h3 className="text-sm font-medium text-slate-500 uppercase mb-4">Change Admin Password</h3>
                        <ChangeAdminPassword />
                    </div>
                </div>
            )}
        </div>
    );
};

const ChangeAdminPassword = () => {
    const [passwords, setPasswords] = useState({ current: '', new: '', confirm: '' });
    const { addToast } = useNotification();

    const handleChangePassword = async (e: React.FormEvent) => {
        e.preventDefault();
        if (passwords.new !== passwords.confirm) {
            addToast("New passwords do not match!", 'error');
            return;
        }

        const adminUser = await db.users.where('role').equals('admin').first();
        if (adminUser && adminUser.password === passwords.current) {
            await db.users.update(adminUser.id!, { password: passwords.new });
            addToast("Admin Password Updated Successfully", 'success');
            setPasswords({ current: '', new: '', confirm: '' });
        } else {
            addToast("Current password is incorrect", 'error');
        }
    };

    return (
        <form onSubmit={handleChangePassword} className="space-y-4 max-w-md">
            <div>
                <input
                    type="password"
                    placeholder="Current Password"
                    value={passwords.current}
                    onChange={e => setPasswords({ ...passwords, current: e.target.value })}
                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                    required
                />
            </div>
            <div>
                <input
                    type="password"
                    placeholder="New Password"
                    value={passwords.new}
                    onChange={e => setPasswords({ ...passwords, new: e.target.value })}
                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                    required
                />
            </div>
            <div>
                <input
                    type="password"
                    placeholder="Confirm New Password"
                    value={passwords.confirm}
                    onChange={e => setPasswords({ ...passwords, confirm: e.target.value })}
                    className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                    required
                />
            </div>
            <button
                type="submit"
                className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg font-medium transition-colors"
            >
                Update Password
            </button>
        </form>
    );
};

export default BusinessProfile;

import React, { useState, useEffect } from 'react';
import { X, FileText, Calendar, ArrowUpRight, ArrowDownLeft, Printer } from 'lucide-react';
import { db, type Invoice } from '../../services/db';
import { generateInvoicePDF } from '../../services/invoiceGenerator';

interface CustomerHistoryModalProps {
    customerId: number;
    onClose: () => void;
}

type LedgerItem = {
    id: string;
    date: Date;
    type: 'invoice' | 'payment' | 'pos_payment'; // pos_payment = initial payment on invoice
    description: string;
    debit: number; // Increase Balance (Purchase)
    credit: number; // Decrease Balance (Payment)
    refId?: number; // Invoice ID or Payment ID
    data?: any; // Full object for actions
};

const CustomerHistoryModal: React.FC<CustomerHistoryModalProps> = ({ customerId, onClose }) => {
    const [ledger, setLedger] = useState<LedgerItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [customerName, setCustomerName] = useState('');
    const [balance, setBalance] = useState(0);

    useEffect(() => {
        const loadHistory = async () => {
            try {
                const customer = await db.customers.get(customerId);
                setCustomerName(customer?.name || 'Customer');
                setBalance(customer?.balance || 0);

                const invoices = await db.invoices.where('customerId').equals(customerId).toArray();
                const payments = await db.customerPayments.where('customerId').equals(customerId).toArray();

                const items: LedgerItem[] = [];

                // 1. Convert Invoices to Debit (Full Amount)
                invoices.forEach(inv => {
                    items.push({
                        id: `INV-${inv.id}`,
                        date: inv.createdAt,
                        type: 'invoice',
                        description: `Invoice #${inv.invoiceNumber}`,
                        debit: inv.grandTotal,
                        credit: 0,
                        refId: inv.id,
                        data: inv
                    });

                    // 2. If Invoice had an initial payment, add as Credit (POS Payment)
                    if (inv.paidAmount > 0) {
                        items.push({
                            id: `POS-PAY-${inv.id}`,
                            date: inv.createdAt, // Same time
                            type: 'pos_payment',
                            description: `Payment for #${inv.invoiceNumber}`,
                            debit: 0,
                            credit: inv.paidAmount,
                            refId: inv.id
                        });
                    }
                });

                // 3. Add Manual Payments
                payments.forEach(pay => {
                    items.push({
                        id: `PAY-${pay.id}`,
                        date: pay.date,
                        type: 'payment',
                        description: `Payment Received (${pay.paymentMode})`,
                        debit: 0,
                        credit: pay.amount,
                        refId: pay.id
                    });
                });

                // Sort Descending (Newest First)
                items.sort((a, b) => b.date.getTime() - a.date.getTime());

                setLedger(items);
            } catch (error) {
                console.error("Failed to load history", error);
            } finally {
                setLoading(false);
            }
        };
        loadHistory();
    }, [customerId]);

    const handlePrintInvoice = async (invoice: Invoice) => {
        const savedBusiness = localStorage.getItem('businessDetails'); // Check inconsistency: 'businessDetails' vs 'businessProfile' used in PosTerminal? 
        // In InvoiceGenerator we use 'businessDetails'. In PosTerminal I saw 'businessProfile' used for thermal?
        // Let's standardise on `businessDetails` as per settings.
        const business = savedBusiness ? JSON.parse(savedBusiness) : {};

        // Re-generate using the robust generator (which handles both thermal/regular logic internally via config)
        await generateInvoicePDF(invoice, business);
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-in fade-in">
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-4xl max-h-[85vh] flex flex-col overflow-hidden">
                <div className="p-6 border-b border-gray-100 dark:border-slate-700 flex justify-between items-center bg-gray-50 dark:bg-slate-900/50">
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                            <FileText className="w-5 h-5 text-indigo-600" />
                            {customerName}
                        </h2>
                        <span className={`text-sm font-semibold ${balance > 0 ? 'text-red-500' : 'text-green-600'}`}>
