export default CustomerHistoryModal;

import React, { useState, useEffect } from 'react';
import { Plus, Users, Trash2, Edit, Wallet } from 'lucide-react';
import { db, type Customer } from '../../services/db';
import { useNotification } from '../../contexts/NotificationContext';
import CustomerForm from './CustomerForm';
import CustomerHistoryModal from './CustomerHistoryModal';
import CustomerPaymentModal from './CustomerPaymentModal';

const CustomerList: React.FC = () => {
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [showHistory, setShowHistory] = useState<number | null>(null);
    const [showPayment, setShowPayment] = useState<Customer | null>(null);
    const [editingCustomer, setEditingCustomer] = useState<Customer | undefined>(undefined);
    const { addToast } = useNotification();

    const fetchCustomers = async () => {
        try {
            const data = await db.customers.toArray();
            setCustomers(data);
        } catch (error) {
            console.error(error);
            addToast('Failed to load customers', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCustomers();
    }, []);

    const handleDelete = async (id: number) => {
        if (!confirm('Are you sure you want to delete this customer?')) return;
        try {
            await db.customers.delete(id);
            addToast('Customer deleted successfully', 'success');
            fetchCustomers();
        } catch {
            addToast('Failed to delete customer', 'error');
        }
    };

    const handleEdit = (customer: Customer) => {
        setEditingCustomer(customer);
        setShowForm(true);
    };

    const handleFormClose = () => {
        setShowForm(false);
        setEditingCustomer(undefined);
        fetchCustomers();
    };

    if (loading) return <div className="p-6 dark:text-white">Loading customers...</div>;

    return (
        <div className="p-6 space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold flex items-center gap-2 dark:text-white">
                    <Users className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
                    Customer Management
                </h1>
                <button
                    onClick={() => setShowForm(true)}
                    className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700"
                >
                    <Plus className="w-4 h-4" />
                    Add Customer
                </button>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg border border-indigo-100 dark:border-slate-700 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-indigo-50 dark:bg-slate-700 border-b border-indigo-100 dark:border-slate-600">
                        <tr>
                            <th className="p-4 font-semibold text-indigo-900 dark:text-indigo-200">Name</th>
                            <th className="p-4 font-semibold text-indigo-900 dark:text-indigo-200">Phone</th>
                            <th className="p-4 font-semibold text-indigo-900 dark:text-indigo-200">Total Spent</th>
                            <th className="p-4 font-semibold text-indigo-900 dark:text-indigo-200">Credit Balance</th>
                            <th className="p-4 font-semibold text-indigo-900 dark:text-indigo-200 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-indigo-50 dark:divide-slate-700">
                        {customers.map((customer) => (
                            <tr key={customer.id} className="hover:bg-indigo-50/50 dark:hover:bg-slate-700/50 transition-colors">
                                <td className="p-4 font-medium text-gray-900 dark:text-white">{customer.name}</td>
                                <td className="p-4 text-gray-600 dark:text-slate-400">{customer.phone}</td>
                                <td className="p-4 font-medium text-green-600 dark:text-green-400">
                                    ${(customer.totalSpent || 0).toFixed(2)}
                                </td>
                                <td className="p-4 font-bold">
                                    <span className={(customer.balance || 0) > 0 ? 'text-red-500' : 'text-slate-500 dark:text-slate-400'}>
                                        ${(customer.balance || 0).toFixed(2)}
                                    </span>
                                </td>
                                <td className="p-4 text-right flex justify-end gap-2">
                                    {(customer.balance || 0) > 0 && (
                                        <button
                                            onClick={() => setShowPayment(customer)}
                                            className="text-xs flex items-center gap-1 bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 px-2 py-1 rounded hover:bg-green-200 transition-colors"
                                            title="Receive Payment"
                                        >
                                            <Wallet size={12} /> Pay
                                        </button>
                                    )}
                                    <button
                                        onClick={() => setShowHistory(customer.id!)}
                                        className="text-xs bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400 px-2 py-1 rounded hover:bg-indigo-200 transition-colors"
                                    >
                                        History
                                    </button>
                                    <button
                                        onClick={() => handleEdit(customer)}
                                        className="text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => customer.id && handleDelete(customer.id)}
                                        className="text-gray-400 hover:text-red-600 dark:hover:text-red-400 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </td>
                            </tr>
                        ))}
                        {customers.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-gray-500 dark:text-slate-400">
                                    No customers found. Add your first customer!
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* History Modal */}
            {showHistory && (
                <CustomerHistoryModal
                    customerId={showHistory}
                    onClose={() => setShowHistory(null)}
                />
            )}

            {/* Payment Modal */}
            {showPayment && (
                <CustomerPaymentModal
                    customer={showPayment}
                    onClose={() => setShowPayment(null)}
                    onPaymentComplete={fetchCustomers}
                />
            )}

            {/* Form Modal */}
            {showForm && (
                <CustomerForm
                    key={editingCustomer?.id || 'new'}
                    customer={editingCustomer}
                    onClose={handleFormClose}
                    onSave={fetchCustomers}
                />
            )}
        </div>
    );
};

export default CustomerList;

import React, { useState } from 'react';
import { X, DollarSign, Wallet } from 'lucide-react';
import { db, type Customer } from '../../services/db';
import { useNotification } from '../../contexts/NotificationContext';

interface CustomerPaymentModalProps {
    customer: Customer;
    onClose: () => void;
    onPaymentComplete: () => void;
}

const CustomerPaymentModal: React.FC<CustomerPaymentModalProps> = ({ customer, onClose, onPaymentComplete }) => {
    const [amount, setAmount] = useState('');
    const [note, setNote] = useState('');
    const [paymentMode, setPaymentMode] = useState<'cash' | 'card' | 'upi'>('cash');
    const { addToast } = useNotification();

    const handlePayment = async () => {
        const payAmount = parseFloat(amount);
        if (!payAmount || payAmount <= 0) {
            addToast('Please enter a valid amount', 'error');
            return;
        }

        try {
            // 1. Record Payment
            await db.customerPayments.add({
                customerId: customer.id!,
                amount: payAmount,
                date: new Date(),
                paymentMode,
                note
            });

            // 2. Update Customer Balance
            // Balance decreases when they pay
            const newBalance = (customer.balance || 0) - payAmount;

            await db.customers.update(customer.id!, {
                balance: newBalance
            });

            addToast('Payment recorded successfully', 'success');
            onPaymentComplete();
            onClose();
        } catch (error) {
            console.error(error);
            addToast('Failed to record payment', 'error');
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-2xl shadow-xl overflow-hidden animate-in fade-in zoom-in-95">
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/50">
                    <div>
                        <h2 className="text-xl font-bold dark:text-white">Receive Payment</h2>
                        <p className="text-sm text-slate-500">for {customer.name}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
                        <X size={20} className="text-slate-500" />
                    </button>
                </div>

                <div className="p-6 space-y-4">
                    <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-100 dark:border-blue-800 flex justify-between items-center">
                        <span className="text-blue-800 dark:text-blue-300 font-medium">Current Credit Balance</span>
                        <span className="text-2xl font-bold text-blue-700 dark:text-blue-400">${(customer.balance || 0).toFixed(2)}</span>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Amount Received</label>
                        <div className="relative">
                            <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                            <input
                                type="number"
                                value={amount}
                                onChange={(e) => setAmount(e.target.value)}
                                className="w-full pl-10 p-3 rounded-lg border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-700 focus:ring-2 focus:ring-blue-500 outline-none dark:text-white"
                                placeholder="0.00"
                                autoFocus
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Payment Mode</label>
                        <div className="grid grid-cols-3 gap-2">
                            {['cash', 'card', 'upi'].map(mode => (
                                <button
                                    key={mode}
                                    onClick={() => setPaymentMode(mode as any)}
                                    className={`p-2 rounded-lg border text-sm font-medium capitalize ${paymentMode === mode
                                        ? 'bg-blue-600 text-white border-blue-600'
                                        : 'bg-white dark:bg-slate-700 border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-300 hover:bg-slate-50'
                                        }`}
                                >
                                    {mode}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Note (Optional)</label>
                        <input
                            type="text"
                            value={note}
                            onChange={(e) => setNote(e.target.value)}
                            className="w-full p-3 rounded-lg border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-700 focus:ring-2 focus:ring-blue-500 outline-none dark:text-white"
                            placeholder="Reference ID, comments..."
                        />
                    </div>
                </div>

                <div className="p-6 border-t border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50 flex gap-3">
                    <button onClick={onClose} className="flex-1 py-3 rounded-xl font-medium text-slate-600 hover:bg-slate-200 dark:text-slate-300 dark:hover:bg-slate-800 transition-colors">
                        Cancel
                    </button>
                    <button
                        onClick={handlePayment}
                        className="flex-1 py-3 bg-green-600 hover:bg-green-700 text-white rounded-xl font-bold shadow-lg shadow-green-500/30 flex items-center justify-center gap-2"
                    >
                        <Wallet size={18} />
                        Confirm Payment
                    </button>
                </div>
            </div>
        </div>
    );
};

