import React from 'react';
import { db } from '../services/db';
import { useLiveQuery } from 'dexie-react-hooks';
import {
    DollarSign,
    TrendingUp,
    TrendingDown,
    AlertCircle
} from 'lucide-react';
import { format } from 'date-fns';
import {
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
    AreaChart,
    Area
} from 'recharts';

import { useNotification } from '../contexts/NotificationContext';

interface StatCardProps {
    title: string;
    value: string | number;
    icon: React.ElementType;
    color: string;
    subValue?: string;
}

const StatCard = ({ title, value, icon: Icon, color, subValue }: StatCardProps) => (
    <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
        <div className="flex justify-between items-start">
            <div>
                <p className="text-slate-500 text-sm font-medium uppercase tracking-wide">{title}</p>
                <h3 className="text-3xl font-bold mt-2 dark:text-white">{value}</h3>
                {subValue && <p className={`text-sm mt-2 ${subValue.startsWith('+') ? 'text-green-500' : 'text-red-500'}`}>{subValue}</p>}
            </div>
            <div className={`p-4 rounded-xl ${color}`}>
                <Icon size={24} className="text-white" />
            </div>
        </div>
    </div>
);

const Dashboard: React.FC = () => {
    const today = new Date();
    const { checkReminders } = useNotification();

    React.useEffect(() => {
        checkReminders();
    }, []);

    const invoices = useLiveQuery(() => db.invoices.toArray(), []);
    const expenses = useLiveQuery(() => db.expenses.toArray(), []);
    const lowStockItems = useLiveQuery(() =>
        db.items.filter(i => i.stock <= i.minStock).toArray(), []
    );

    // Calculate Metrics
    const totalSales = invoices?.reduce((sum, inv) => sum + inv.grandTotal, 0) || 0;
    const totalExpenses = expenses?.reduce((sum, exp) => sum + exp.amount, 0) || 0;
    const netProfit = totalSales - totalExpenses; // Simplified Profit (Sales - Expenses) - COGS ideally

    const todaySales = invoices
        ?.filter(inv => new Date(inv.createdAt).toDateString() === today.toDateString())
        .reduce((sum, inv) => sum + inv.grandTotal, 0) || 0;

    // Chart Data Preparation (Last 7 Days)
    const chartData = Array.from({ length: 7 }).map((_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        const dateStr = d.toDateString();

        const sales = invoices
            ?.filter(inv => new Date(inv.createdAt).toDateString() === dateStr)
            .reduce((sum, inv) => sum + inv.grandTotal, 0) || 0;

        return {
            name: format(d, 'EEE'),
            sales: sales
        };
    });

    return (
        <div className="space-y-8">
            {/* Header */}
            <div>
                <h1 className="text-3xl font-bold dark:text-white flex items-center gap-3">
                    Dashboard Overview
                    <span className="text-sm bg-blue-600/10 text-blue-600 border border-blue-200 px-3 py-1 rounded-full font-medium">v2.0 New UI</span>
                </h1>
                <p className="text-slate-500 mt-1">Welcome back! Here's what's happening today.</p>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard
                    title="Total Revenue"
                    value={`$${totalSales.toFixed(2)}`}
                    icon={DollarSign}
                    color="bg-blue-500"
                    subValue={`+${todaySales.toFixed(2)} Today`}
                />
                <StatCard
                    title="Net Profit"
                    value={`$${netProfit.toFixed(2)}`}
                    icon={TrendingUp}
                    color="bg-green-500"
                />
                <StatCard
                    title="Total Expenses"
                    value={`$${totalExpenses.toFixed(2)}`}
                    icon={TrendingDown}
                    color="bg-red-500"
                />
                <StatCard
                    title="Low Stock Items"
                    value={lowStockItems?.length || 0}
                    icon={AlertCircle}
                    color="bg-orange-500"
                    subValue="Action Needed"
                />
            </div>

            {/* Charts & Tables */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Chart */}
                <div className="lg:col-span-2 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
                    <h3 className="text-lg font-bold mb-6 dark:text-white">Sales Overview (Last 7 Days)</h3>
                    <div className="h-80">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={chartData}>
                                <defs>
                                    <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                                <YAxis axisLine={false} tickLine={false} />
                                <Tooltip />
                                <Area type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Low Stock List */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
                    <h3 className="text-lg font-bold mb-6 dark:text-white flex items-center gap-2">
                        <AlertCircle size={20} className="text-orange-500" /> Low Stock Alerts
                    </h3>
                    <div className="space-y-4">
                        {lowStockItems?.slice(0, 5).map(item => (
                            <div key={item.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg">
                                <div>
                                    <p className="font-medium dark:text-white line-clamp-1">{item.name}</p>
                                    <p className="text-xs text-slate-500">Min: {item.minStock}</p>
                                </div>
                                <span className="px-3 py-1 bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-full text-xs font-bold">
                                    {item.stock} left
                                </span>
                            </div>
                        ))}
                        {lowStockItems?.length === 0 && (
                            <p className="text-slate-500 text-sm text-center py-8">All items are well stocked!</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

