import React, { useState } from 'react';
import { CreditCard, Banknote, Smartphone, Printer, Ban } from 'lucide-react';
import { db } from '../../services/db';
import type { Invoice, InvoiceItem } from '../../services/db';
import { useNotification } from '../../contexts/NotificationContext';
import { generateInvoicePDF } from '../../services/invoiceGenerator';
import { generateThermalInvoice } from '../../services/thermalPrinter';
import Modal from '../../components/UI/Modal';
import { useSettings } from '../../contexts/SettingsContext';

interface CheckoutModalProps {
    isOpen: boolean;
    onClose: () => void;
    subTotal: number;
    preCalculatedTax?: number;
    items: InvoiceItem[];
    customerName?: string;
    customerId?: number;
    customerVatNumber?: string; // New Prop
    onConfirm: (data: Partial<Invoice>) => void;
}

const CheckoutModal: React.FC<CheckoutModalProps> = ({ isOpen, onClose, subTotal, preCalculatedTax, items, customerName, customerId, customerVatNumber, onConfirm }) => {
    // Moved early return to after hooks to satisfy Rules of Hooks
    const { addToast } = useNotification();
    const { formatCurrency } = useSettings();

    const [discountPercent, setDiscountPercent] = useState(0);
    const [taxPercent, setTaxPercent] = useState(15); // Default 15% (KSA Standard)
    const [paymentMode, setPaymentMode] = useState<'cash' | 'card' | 'upi' | 'credit'>('cash');
    const [amountPaidInput, setAmountPaidInput] = useState('');
    const [dueDate, setDueDate] = useState('');

    // Load Tax Defaults from Settings
    const [businessDetails, setBusinessDetails] = useState<any>(null);
    React.useEffect(() => {
        const saved = localStorage.getItem('businessDetails');
        if (saved) {
            const parsed = JSON.parse(saved);
            setBusinessDetails(parsed);
            if (parsed.country === 'Saudi Arabia') setTaxPercent(15);
        }
    }, []);

    // const [isTaxEnabled, setIsTaxEnabled] = useState(true); // Removed as always enabled/hidden
    const isTaxEnabled = true;

    const discountAmount = (subTotal * discountPercent) / 100;
    const taxableAmount = subTotal - discountAmount;

    let taxAmount = 0;
    if (isTaxEnabled) {
        if (preCalculatedTax !== undefined) {
            taxAmount = preCalculatedTax * (1 - discountPercent / 100);
        } else {
            taxAmount = (taxableAmount * taxPercent) / 100;
        }
    }

    const grandTotal = taxableAmount + taxAmount;

    // Payment Logic
    // If 'credit' selected: Default Paid = 0
    // If 'cash/card': Default Paid = Grand Total (unless user edits for Split/Partial)

    // We need to initialize Amount Paid when GrandTotal changes ONLY if user hasn't edited it?
    // Or simpler: Just have the input.

    const amountPaid = paymentMode === 'cash' ? grandTotal : (parseFloat(amountPaidInput) || 0);
    const balanceDue = Math.max(0, grandTotal - amountPaid);
    const changeAmount = amountPaid - grandTotal;

    // Validation: Is Credit Allowed?
    const isCreditSale = paymentMode === 'credit' || balanceDue > 0.01; // Tolerance
    const canTakeCredit = !!customerId; // Only if Customer ID exists

    // const { addToast } = useNotification(); // Removed duplicate

    const handleConfirm = async () => {
        // Validation Block
        if (isCreditSale && !canTakeCredit) {
            addToast('Walk-in Customers cannot take Credit. Please select a registered Customer.', 'error');
            return;
        }

        if (paymentMode === 'credit' && !dueDate) {
            addToast('Please select a Due Date for credit sales.', 'error');
            return;
        }

        // Determine Final Status
        let finalStatus: 'paid' | 'pending' | 'partial' = 'paid';
        if (balanceDue > 0.01) {
            finalStatus = amountPaid > 0 ? 'partial' : 'pending';
        }

        try {
            // Generate Sequential Invoice Number
            const lastInvoice = await db.invoices.orderBy('id').last();
            let nextNumber = 1;
            if (lastInvoice && lastInvoice.invoiceNumber) {
                // Remove non-numeric chars to be safe, though we expect pure numbers now
                const lastNumStr = lastInvoice.invoiceNumber.replace(/\D/g, '');
                const lastNum = parseInt(lastNumStr, 10);
                if (!isNaN(lastNum)) {
                    nextNumber = lastNum + 1;
                }
            }
            // Pad to 3 digits (e.g. 001, 050, 100)
            const newInvoiceNumber = nextNumber.toString().padStart(3, '0');

            const invoiceData: any = {
                invoiceNumber: newInvoiceNumber,
                customerName: customerName || "Walk-in Customer",
                customerId: customerId,
                customerVatNumber: customerId ? (customerVatNumber || undefined) : undefined, // Include VAT
                items,
                subTotal,
                discountAmount,
                taxAmount,
                grandTotal,
                paidAmount: paymentMode === 'credit' ? amountPaid : (amountPaid || grandTotal), // If credit, use input. If cash/card, if input empty assume full, else input.
                remainingAmount: paymentMode === 'credit' ? (grandTotal - amountPaid) : (balanceDue > 0 ? balanceDue : 0),
                paymentMode,
                createdAt: new Date(),
                paymentStatus: finalStatus,
                dueDate: (finalStatus !== 'paid' && dueDate) ? new Date(dueDate) : undefined,
                taxRate: taxPercent
            };

            // Fix for "Cash" full payment where input might be empty (implying full) OR "Cash" UI hidden
            if (paymentMode !== 'credit' && (!amountPaidInput || paymentMode === 'cash')) {
                invoiceData.paidAmount = grandTotal;
                invoiceData.remainingAmount = 0;
                invoiceData.paymentStatus = 'paid';
            }

            // 1. Wait for DB Save
            console.log("Attempting to save invoice to DB:", invoiceData);
            await onConfirm(invoiceData);
            console.log("DB Save successful");

            // 2. Determine and Execute Print Strategy
            // 2. Determine and Execute Print Strategy
            if (businessDetails) {
                console.log("Starting Print Process. Config:", businessDetails);
                const printerConfig = JSON.parse(localStorage.getItem('printerConfig') || '{}');
                const printDetails = { ...businessDetails, taxRate: taxPercent };

                if (printerConfig.printerType === 'thermal') {
                    console.log("Generating thermal invoice...");
                    await generateThermalInvoice(invoiceData, printDetails);
                } else {
                    console.log("Generating PDF invoice...");
                    await generateInvoicePDF(invoiceData, printDetails);
                }
                console.log("Print process finished.");
                addToast('Sale completed & Invoice Printed!', 'success');
            } else {
                addToast('Sale completed (Printing Skipped - Check Settings)', 'warning');
            }
        } catch (error) {
            console.error(error);
            addToast('Failed to process sale', 'error');
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            maxWidth="4xl"
            className="h-auto max-h-[90vh] flex flex-col md:flex-row"
        >
            <div className="flex flex-col md:flex-row w-full h-full">
                {/* LEFT SIDE: Configuration */}
                <div className="flex-1 p-8 overflow-y-auto">
                    <div className="flex justify-between items-start mb-8">
                        <div>
                            <h2 className="text-3xl font-bold dark:text-white mb-2">Checkout</h2>
                            <div className="flex items-center gap-2">
                                <div className={`w-2 h-2 rounded-full ${customerId ? 'bg-green-500' : 'bg-slate-300'}`}></div>
                                <span className="font-medium text-slate-600 dark:text-slate-400">
                                    {customerName || "Walk-in Customer"}
                                </span>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-8">
                        {/* Payment Mode */}
                        <div>
                            <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-3">Payment Method</label>
                            <div className="grid grid-cols-2 gap-4">
                                {[
                                    { id: 'cash', icon: Banknote, label: 'Cash' },
                                    { id: 'card', icon: CreditCard, label: 'Card' },
                                    { id: 'upi', icon: Smartphone, label: 'Digital' },
                                    { id: 'credit', icon: Printer, label: 'Credit' }
                                ].map((mode) => (
                                    <button
                                        key={mode.id}
                                        onClick={() => {
                                            setPaymentMode(mode.id as 'cash' | 'card' | 'upi' | 'credit');
                                            if (mode.id === 'credit') setAmountPaidInput('0');
                                            else setAmountPaidInput('');
                                        }}
                                        className={`group relative p-4 rounded-2xl border-2 transition-all duration-200 flex flex-col items-center gap-3 ${paymentMode === mode.id
                                            ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20'
                                            : 'border-slate-100 dark:border-slate-700 hover:border-blue-200 hover:bg-slate-50 dark:hover:bg-slate-800'
                                            }`}
                                    >
                                        <div className={`p-3 rounded-full ${paymentMode === mode.id ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-500 dark:bg-slate-700'}`}>
                                            <mode.icon size={24} />
                                        </div>
                                        <span className={`font-semibold ${paymentMode === mode.id ? 'text-blue-700 dark:text-blue-300' : 'text-slate-600 dark:text-slate-400'}`}>
                                            {mode.label}
                                        </span>
                                        {paymentMode === mode.id && (
                                            <div className="absolute top-3 right-3 w-3 h-3 bg-blue-600 rounded-full"></div>
                                        )}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Validations */}
                        <div className="space-y-3">
                            {isCreditSale && !canTakeCredit && (
                                <div className="bg-red-50 dark:bg-red-900/20 p-4 rounded-xl border border-red-100 dark:border-red-800 flex gap-3 text-red-600 dark:text-red-400">
                                    <Ban className="shrink-0 mt-0.5" />
                                    <div>
                                        <h4 className="font-bold">Credit Not Allowed</h4>
                                        <p className="text-sm opacity-90">Walk-in customers cannot have a balance due. Please select a registered customer.</p>
                                    </div>
                                </div>
                            )}

                            {(paymentMode === 'credit' || balanceDue > 0) && (
                                <div className="bg-orange-50 dark:bg-orange-900/20 p-4 rounded-xl border border-orange-100 dark:border-orange-800 animate-in fade-in">
                                    <label className="block text-xs font-bold uppercase tracking-wider text-orange-700 dark:text-orange-400 mb-2">Due Date Required</label>
                                    <input
                                        type="date"
                                        value={dueDate}
                                        onChange={(e) => setDueDate(e.target.value)}
                                        className="w-full p-3 rounded-lg border border-orange-200 dark:border-orange-700 bg-white dark:bg-slate-800 dark:text-white focus:outline-none focus:ring-2 focus:ring-orange-500"
                                        required
                                    />
                                </div>
                            )}
                        </div>

                        {/* Actions Grid */}
                        <div className="grid grid-cols-2 gap-4">
                            <button onClick={onClose} className="p-4 rounded-xl font-semibold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                                Cancel
                            </button>
                            <button
                                onClick={handleConfirm}
                                disabled={isCreditSale && !canTakeCredit}
                                className="p-4 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl font-bold shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transform active:scale-95 transition-all"
                            >
                                <Printer size={20} />
                                <span>Print Invoice</span>
                            </button>
                        </div>
                    </div>
                </div>

                {/* RIGHT SIDE: Receipt Summary */}
                <div className="w-full md:w-[400px] bg-slate-50 dark:bg-slate-900 border-l border-slate-200 dark:border-slate-700 flex flex-col">
                    <div className="p-8 flex-1 flex flex-col">
                        <h3 className="text-sm font-bold uppercase text-slate-400 mb-6 tracking-wider">Order Summary</h3>

                        {/* Bill Details */}
                        <div className="space-y-4 mb-8 text-slate-600 dark:text-slate-300">
                            <div className="flex justify-between">
                                <span>Subtotal ({items.length} items)</span>
                                <span className="font-medium">{formatCurrency(subTotal)}</span>
                            </div>

                            {/* Discount Input */}
                            <div className="flex justify-between items-center group">
                                <span className="group-focus-within:text-blue-600 transition-colors">Discount</span>
                                <div className="flex items-center gap-2">
                                    <div className="flex text-xs bg-slate-200 dark:bg-slate-800 rounded-lg p-0.5">
                                        {[0, 5, 10].map(d => (
                                            <button
                                                key={d}
                                                onClick={() => setDiscountPercent(d)}
                                                className={`px-2 py-0.5 rounded-md transition-all ${discountPercent === d ? 'bg-white shadow text-black font-bold' : 'text-slate-500 hover:text-slate-700'}`}
                                            >
                                                {d}%
                                            </button>
                                        ))}
                                    </div>
                                    <input
                                        type="number"
                                        value={discountPercent}
                                        onChange={e => setDiscountPercent(Number(e.target.value))}
                                        className="w-12 text-right bg-transparent border-b border-dashed border-slate-300 focus:border-blue-500 outline-none font-medium text-red-500"
                                    />
                                    <span className="text-red-500">-${discountAmount.toFixed(2)}</span>
                                </div>
                            </div>

                            <div className="flex justify-between items-center opacity-80">
                                <span>Tax</span>
                                <span>+${taxAmount.toFixed(2)}</span>
                            </div>
                        </div>

                        {/* Grand Total Card */}
                        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 mb-6">
                            <div className="text-center mb-1">
                                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Grand Total</span>
                            </div>
                            <div className="text-center">
                                <span className="text-4xl font-black text-slate-800 dark:text-white tracking-tight">${grandTotal.toFixed(2)}</span>
                            </div>
                        </div>

                        {/* Payment Input */}
                        {paymentMode !== 'cash' && (
                            <div className="mt-auto">
                                <label className="block text-xs font-bold uppercase text-slate-500 mb-2">
                                    {paymentMode === 'credit' ? 'Down Payment Amount' : 'Amount Tendered'}
                                </label>
                                <div className={`relative rounded-xl overflow-hidden border-2 transition-all ${isCreditSale && !canTakeCredit ? 'border-red-300 bg-red-50' : 'border-blue-100 focus-within:border-blue-500 bg-white dark:bg-slate-800 dark:border-slate-600'}`}>
                                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">$</div>
                                    <input
                                        type="number"
                                        value={amountPaidInput}
                                        onChange={(e) => setAmountPaidInput(e.target.value)}
                                        // eslint-disable-next-line jsx-a11y/no-autofocus
                                        autoFocus
                                        className="w-full pl-10 pr-4 py-4 text-2xl font-bold bg-transparent outline-none text-slate-800 dark:text-white"
                                        placeholder={paymentMode === 'credit' ? "0.00" : grandTotal.toFixed(2)}
                                    />
                                </div>
                            </div>
                        )}

                        {paymentMode === 'cash' && (
                            <div className="mt-auto mb-4 bg-green-50 dark:bg-green-900/20 p-4 rounded-xl border border-green-100 dark:border-green-800 text-center">
                                <span className="block text-green-700 dark:text-green-400 font-bold">Full Cash Payment</span>
                            </div>
                        )}

                        {/* Change/Balance Indicator */}
                        <div className="mt-4 flex items-center justify-between p-4 rounded-xl bg-slate-100 dark:bg-slate-800">
                            {changeAmount >= 0 ? (
                                <>
                                    <span className="font-semibold text-slate-500">Change Due</span>
                                    <span className="text-xl font-bold text-green-600">{formatCurrency(changeAmount)}</span>
                                </>
                            ) : (
                                <>
                                    <span className="font-semibold text-slate-500">Credit Balance Remaining</span>
                                    <span className="text-xl font-bold text-red-500">{formatCurrency(balanceDue)}</span>
                                </>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </Modal>
    );
};

export default CheckoutModal;

import React, { useState, useMemo } from 'react';
import { db } from '../../services/db';
import type { Item, Invoice } from '../../services/db';
import { useLiveQuery } from 'dexie-react-hooks';
import { Search, ShoppingCart, User, CreditCard, Trash2 } from 'lucide-react';
import CheckoutModal from './CheckoutModal';

const PosTerminal: React.FC = () => {
    const [search, setSearch] = useState('');
    const [cart, setCart] = useState<any[]>([]);
    const [customer, setCustomer] = useState<{ id?: number, name: string, phone: string, vatNumber?: string }>({ name: 'Walk-in Customer', phone: '', vatNumber: '' });

    // Load items and customers
    const items = useLiveQuery(
        () => db.items.toArray()
    );
    const customers = useLiveQuery(
        () => db.customers.toArray()
    );
    const [showCustomerSearch, setShowCustomerSearch] = useState(false);
    const [customerSearchTerm, setCustomerSearchTerm] = useState('');

    // Filtered customers for dropdown
    const filteredCustomers = useMemo(() => {
        if (!customers || !customerSearchTerm) return [];
        return customers.filter(c => c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()) || c.phone.includes(customerSearchTerm));
    }, [customers, customerSearchTerm]);

    const selectCustomer = (c: any) => {
        setCustomer({ id: c.id, name: c.name, phone: c.phone, vatNumber: c.vatNumber });
        setCustomerSearchTerm('');
        setShowCustomerSearch(false);
    };

    // Tax Configuration
    const [isTaxExclusiveMode, setIsTaxExclusiveMode] = useState(false); // Default: Inclusive (Tax Included)
    const GLOBAL_TAX_RATE = 15; // Could be dynamic

    const filteredItems = useMemo(() => {
        if (!items) return [];
        return items.filter(i =>
            i.name.toLowerCase().includes(search.toLowerCase()) ||
            i.barcode.includes(search)
        );
    }, [items, search]);

    // Cart Logic
    const addToCart = (item: Item) => {
        const existing = cart.find(c => c.itemId === item.id);
        if (existing) {
            setCart(cart.map(c => {
                if (c.itemId === item.id) {
                    const newQty = c.quantity + 1;
                    return { ...c, quantity: newQty, total: newQty * c.price };
                }
                return c;
            }));
        } else {
            setCart([...cart, {
                itemId: item.id,
                name: item.name,
                price: item.salePrice,
                quantity: 1,
                total: item.salePrice,
                unit: item.unit || 'pc',
                taxType: item.taxType || 'exclusive',
                taxRate: item.taxRate || 0
            }]);
        }
    };

    const updateQuantity = (itemId: number, newQty: number) => {
        if (newQty < 1) return;
        setCart(cart.map(c => {
            if (c.itemId === itemId) {
                return { ...c, quantity: newQty, total: newQty * c.price };
            }
            return c;
        }));
    };

    const updatePrice = (itemId: number, newPrice: number) => {
        setCart(cart.map(c => {
            if (c.itemId === itemId) {
                return { ...c, price: newPrice, total: c.quantity * newPrice };
            }
            return c;
        }));
    };

    const updateUnit = (itemId: number, newUnit: string) => {
        setCart(cart.map(c => {
            if (c.itemId === itemId) {
                return { ...c, unit: newUnit };
            }
            return c;
        }));
    };

    const removeFromCart = (itemId: number) => {
        setCart(cart.filter(c => c.itemId !== itemId));
    };

    const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

    // Calculate Totals handling Inclusive/Exclusive
    // This GrandTotal is what is displayed in the "Charge" button.
    // If inclusive, price is final.
    // If exclusive, price is base. TAX IS EXTRA?
    // User says: "if include dont add vat". 
    // This implies for inclusive items, we don't add ANYTHING.
    // For exclusive items, do we add it here? "also add vat from the cart side" - usually done at checkout.
    // Let's assume the cart shows Line Totals (Price * Qty). 
    // If exclusive, Tax is added at CheckoutModal usually.
    // But if we have mixed, we need to pass a "Tax Amount" pre-calculated or flags.

    // Let's look at passed props to CheckoutModal: subTotal={grandTotal}.
    // If we want to implement "don't add vat", we should probably ensure logic in CheckoutModal respects this.
    // However, if we simply calculate the Tax needed for Exclusive items here and pass it?

    // Let's stick to: Cart "Total" = Price * Qty.
    // We will calculate expected tax.

    const cartTax = cart.reduce((sum, item) => {
        // If Global "Add Tax" mode is ON, we treat ALL items as Exclusive (Base Price) and add Tax on top.
        // If OFF, we treat prices as Final (Inclusive).
        // Exception: If item ITSELF is marked 'exclusive' explicitly in DB? 
        // User said: "clickable option for tax... if selected we can add tax... if not it already tax included"
        // This implies the TOGGLE overrides/controls the behavior for the current cart to add EXTRA tax.

        if (isTaxExclusiveMode) {
            return sum + (item.total * (GLOBAL_TAX_RATE / 100));
        }
        return sum;
        // Note: If item.taxType was 'exclusive' before, we ignore it? 
        // Let's assume the Toggle is the master switch for "Adding VAT on top".
    }, 0);

    const cartSubTotal = cart.reduce((sum, item) => sum + item.total, 0);
    const payableTotal = cartSubTotal + cartTax;

    const handleCheckoutComplete = async (paymentDetails: Partial<Invoice>) => {
        // Prepare Invoice Data
        const invoice: Invoice = {
            invoiceNumber: `INV-${Date.now()}`,
            customerName: customer.name || 'Walk-in Customer',
            customerId: customer.id, // Store Customer ID for linking
            customerContact: customer.phone,
            customerVatNumber: customer.vatNumber, // Pass captured VAT
            // Assuming customer object might have vatNumber if we select from DB, but here it's local state.
            // We should ideally allow selecting customer or adding VAT no.
            // For now, let's rely on what's passed or defaults.
            // If CheckoutModal collects it, it comes in paymentDetails?
            // CheckoutModal doesn't collect VAT No yet. 
            // We will add that to CheckoutModal or Customer Input?
            // Let's add simple VAT input here or rely on Customer DB lookup if we implemented it.
            // Since we only have Name/Phone state here:
            // Let's pass null for now or update Customer State to include VAT?

            items: cart,
            subTotal: cartSubTotal,
            taxAmount: paymentDetails.taxAmount || cartTax,
            discountAmount: paymentDetails.discountAmount || 0,
            grandTotal: paymentDetails.grandTotal || payableTotal,
            paidAmount: paymentDetails.paidAmount || payableTotal, // Default to total if missing (e.g. quick cash)
            remainingAmount: paymentDetails.remainingAmount || 0,
            paymentMode: paymentDetails.paymentMode || 'cash',
            paymentStatus: paymentDetails.paymentStatus || 'paid',
            dueDate: paymentDetails.dueDate,
            taxRate: paymentDetails.taxRate || GLOBAL_TAX_RATE,
            createdAt: new Date()
        };

        try {
            await db.invoices.add(invoice);

            // Link Sale to Customer Logic
            if (customer.id) {
                // Fetch fresh to avoid race conditions
                const dbCustomer = await db.customers.get(customer.id);
                if (dbCustomer) {
                    const newTotalSpent = (dbCustomer.totalSpent || 0) + (paymentDetails.grandTotal || payableTotal);
                    // Add remaining amount to balance (Ledger)
                    // If paymentDetails.remainingAmount is set (from CheckoutModal), use it.
                    // Otherwise default to 0 (Paid).
                    const addedBalance = paymentDetails.remainingAmount || 0;
                    const newBalance = (dbCustomer.balance || 0) + addedBalance;

                    await db.customers.update(customer.id, {
                        totalSpent: newTotalSpent,
                        balance: newBalance
                    });
                }
            }

            // ... existing stock update code ...
            for (const cartItem of cart) {
                const item = await db.items.get(cartItem.itemId);
                if (item) {
                    await db.items.update(item.id!, { stock: item.stock - cartItem.quantity });
                }
            }

            setCart([]);
            setCustomer({ name: 'Walk-in Customer', phone: '', vatNumber: '' }); // Reset
            setIsCheckoutOpen(false);

            // Toast handled by CheckoutModal
            // console.log("Sale Saved");
        } catch (e) {
            console.error("Sale Save failed", e);
            throw e; // CheckOutModal will catch this
        }
    };

    return (
        <div className="flex h-[calc(100vh-6rem)] gap-6">
            {/* ... Left Side ... */}
            <div className="w-[65%] flex flex-col gap-6">
                {/* Same Search and Grid */}
                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex gap-4">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Search / Scan Barcode..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-600 bg-slate-50 dark:bg-slate-700 dark:text-white outline-none focus:ring-2 focus:ring-blue-500"
                            autoFocus
                        />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto grid grid-cols-3 lg:grid-cols-4 gap-4 content-start pr-2">
                    {filteredItems?.map(item => (
                        <button
                            key={item.id}
                            onClick={() => addToCart(item)}
                            className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 hover:shadow-md hover:border-blue-500 transition-all text-left flex flex-col justify-between h-40 group"
                        >
                            <div>
                                <h3 className="font-semibold text-slate-800 dark:text-white line-clamp-2">{item.name}</h3>
                                <p className="text-xs text-slate-500 mt-1">{item.stock} {item.unit || 'pc'} in stock</p>
                            </div>
                            <div className="mt-2">
                                <span className="text-lg font-bold text-blue-600 dark:text-blue-400">
                                    ${item.salePrice}
                                </span>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Cart - Right Side (35%) */}
            <div className="w-[35%] bg-white dark:bg-slate-800 rounded-xl shadow-lg border border-slate-200 dark:border-slate-700 flex flex-col overflow-hidden">
                {/* Customer Header */}
                <div className="p-4 bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                    <div className="flex items-center gap-2 text-slate-500 mb-2">
                        <User size={16} /> <span className="text-xs font-semibold uppercase">Customer Details</span>
                    </div>
                    <div className="relative">
                        <input
                            type="text"
                            value={customer.name}
                            onChange={(e) => {
                                setCustomer({ ...customer, name: e.target.value });
                                setCustomerSearchTerm(e.target.value);
                                setShowCustomerSearch(true);
                            }}
                            onFocus={() => setShowCustomerSearch(true)}
                            placeholder="Search Customer by Name or Phone..."
                            className="w-full bg-transparent border-b border-dashed border-slate-300 dark:border-slate-600 focus:border-blue-500 outline-none pb-1 dark:text-white font-medium"
                        />
                        {showCustomerSearch && customerSearchTerm && (
                            <div className="absolute top-full left-0 w-full z-50 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl mt-1 max-h-48 overflow-y-auto">
                                <div
                                    className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer text-sm text-blue-600"
                                    onClick={() => {
                                        // Keep what typed as new name
                                        setShowCustomerSearch(false);
                                    }}
                                >
                                    + Use "{customerSearchTerm}"
                                </div>
                                {filteredCustomers?.map(c => (
                                    <div
                                        key={c.id}
                                        onClick={() => selectCustomer(c)}
                                        className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer border-b border-slate-100 dark:border-slate-700 last:border-0"
                                    >
                                        <div className="flex justify-between">
                                            <div className="font-medium text-slate-800 dark:text-white">{c.name}</div>
                                            {c.balance > 0 && <span className="text-xs text-red-500 font-bold">Due: ${c.balance.toFixed(2)}</span>}
                                        </div>
                                        <div className="text-xs text-slate-500">{c.phone} {c.vatNumber && `| VAT: ${c.vatNumber}`}</div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {cart.map((item) => (
                        <div key={item.itemId} className="flex flex-col p-3 bg-slate-50 dark:bg-slate-700/30 rounded-lg gap-2">
                            <div className="flex justify-between items-start">
                                <div className="font-medium text-slate-800 dark:text-white">{item.name}</div>
                                <button onClick={() => removeFromCart(item.itemId)} className="text-red-400 hover:text-red-600"><Trash2 size={16} /></button>
                            </div>

                            <div className="flex items-center gap-2 text-xs text-slate-500">
                                <div className="flex-1 flex gap-2">
                                    <div className="flex flex-col w-20">
                                        <label className="text-[10px] uppercase">Price</label>
                                        <input
                                            type="number"
                                            value={item.price}
                                            onChange={(e) => updatePrice(item.itemId, parseFloat(e.target.value))}
                                            className="w-full px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 focus:border-blue-500 outline-none"
                                        />
                                    </div>
                                    <div className="flex flex-col w-16">
                                        <label className="text-[10px] uppercase">Qty</label>
                                        <input
                                            type="number"
                                            value={item.quantity}
                                            onChange={(e) => updateQuantity(item.itemId, parseFloat(e.target.value))}
                                            className="w-full px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 focus:border-blue-500 outline-none"
                                        />
                                    </div>
                                    <div className="flex flex-col w-16">
                                        <label className="text-[10px] uppercase">Unit</label>
                                        <input
                                            type="text"
                                            value={item.unit}
                                            onChange={(e) => updateUnit(item.itemId, e.target.value)}
                                            className="w-full px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 focus:border-blue-500 outline-none"
                                        />
                                    </div>
                                </div>
                                <div className="flex flex-col items-end">
                                    <span className="font-bold text-slate-800 dark:text-blue-300 text-sm">
                                        ${item.total.toFixed(2)}
                                    </span>
                                    {item.taxType === 'inclusive' ?
                                        <span className="text-[10px] text-green-600 font-semibold">Tax Incl.</span> :
                                        <span className="text-[10px] text-orange-500">Tax Excl.</span>
                                    }
                                </div>
                            </div>
                        </div>
                    ))}
                    {cart.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                            <ShoppingCart size={48} />
                            <p className="mt-2 text-sm">Cart is empty</p>
                        </div>
                    )}
                </div>

                {/* Footer / Totals */}
                <div className="p-6 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-700 space-y-3">
                    <div className="flex justify-between text-sm dark:text-slate-400">
                        <span>Subtotal</span>
                        <span>${cartSubTotal.toFixed(2)}</span>
                    </div>
                    {cartTax > 0 && (
                        <div className="flex justify-between text-sm text-slate-500">
                            <span>Tax ({GLOBAL_TAX_RATE}%)</span>
                            <span>${cartTax.toFixed(2)}</span>
                        </div>
                    )}
                    <div className="flex items-center justify-between py-2 border-t border-dashed border-slate-200 dark:border-slate-700">
                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">Add VAT (15%)</span>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={isTaxExclusiveMode} onChange={(e) => setIsTaxExclusiveMode(e.target.checked)} className="sr-only peer" />
                            <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        </label>
                    </div>
                    <div className="flex justify-between font-bold text-lg dark:text-white">
                        <span>Total</span>
                        <span>${payableTotal.toFixed(2)}</span>
                    </div>

                    <button
                        onClick={() => setIsCheckoutOpen(true)}
                        disabled={cart.length === 0}
                        className="w-full mt-4 bg-green-600 hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-green-900/20 active:scale-[0.98] transition-all flex justify-center items-center gap-2"
                    >
                        <CreditCard size={24} />
                        Charge ${payableTotal.toFixed(2)}
                    </button>
                </div>
            </div>

            <CheckoutModal
                isOpen={isCheckoutOpen}
                onClose={() => setIsCheckoutOpen(false)}
                subTotal={cartSubTotal}
                preCalculatedTax={cartTax}
                items={cart}
                customerName={customer.name}
                customerId={customer.id}
                customerVatNumber={customer.vatNumber} // Added Prop
                onConfirm={handleCheckoutComplete}
            />
        </div>
    );
};

export default PosTerminal;

import { useState } from 'react';
import { db } from '../../services/db';
import type { Item, Purchase } from '../../services/db';
import { useLiveQuery } from 'dexie-react-hooks';
import { Plus, Search, Trash2, Save } from 'lucide-react';
import { useNotification } from '../../contexts/NotificationContext';
import Modal from '../../components/UI/Modal';
import { useSettings } from '../../contexts/SettingsContext';

const PurchaseOrders = () => {
    const { addToast, addNotification } = useNotification();
    const { formatCurrency, formatDate } = useSettings();
    const [isModalOpen, setIsModalOpen] = useState(false);

    // Form State
    const [supplier, setSupplier] = useState('');
    const [orderNumber, setOrderNumber] = useState('');
    const [orderDate, setOrderDate] = useState(new Date().toISOString().split('T')[0]);
    const [dueDate, setDueDate] = useState('');
    const [orderItems, setOrderItems] = useState<any[]>([]);

    // Financials & Payment
    const [paidAmount, setPaidAmount] = useState<string>(''); // Advance Amt
    const [paymentType, setPaymentType] = useState('cash');
    const [notes, setNotes] = useState('');

    const [searchTerm, setSearchTerm] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const purchases = useLiveQuery(() => db.purchases.reverse().toArray(), []);

    const filteredPurchases = purchases?.filter(po => {
        if (startDate) {
            const poDate = new Date(po.date);
            const start = new Date(startDate);
            poDate.setHours(0, 0, 0, 0);
            start.setHours(0, 0, 0, 0);
            if (poDate < start) return false;
        }
        if (endDate) {
            const poDate = new Date(po.date);
            const end = new Date(endDate);
            poDate.setHours(0, 0, 0, 0);
            end.setHours(0, 0, 0, 0);
            if (poDate > end) return false;
        }
        return true;
    });
    const inventoryItems = useLiveQuery(() => db.items.toArray(), []);

    const filteredInventory = inventoryItems?.filter(i =>
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const addToOrder = (item: Item) => {
        const existing = orderItems.find(i => i.itemId === item.id);
        if (existing) {
            setOrderItems(orderItems.map(i =>
                i.itemId === item.id ? { ...i, quantity: i.quantity + 1 } : i
            ));
        } else {
            setOrderItems([...orderItems, {
                itemId: item.id,
                name: item.name,
                quantity: 1,
                cost: item.purchasePrice
            }]);
        }
    };

    const updateOrderItem = (itemId: number, field: string, value: number) => {
        setOrderItems(orderItems.map(i =>
            i.itemId === itemId ? { ...i, [field]: value } : i
        ));
    };

    const removeOrderItem = (itemId: number) => {
        setOrderItems(orderItems.filter(i => i.itemId !== itemId));
    };

    const totalAmount = orderItems.reduce((sum, item) => sum + (item.cost * item.quantity), 0);
    const advance = parseFloat(paidAmount) || 0;
    const balanceDue = Math.max(0, totalAmount - advance);

    const resetForm = () => {
        setSupplier('');
        setOrderNumber('');
        setOrderDate(new Date().toISOString().split('T')[0]);
        setDueDate('');
        setOrderItems([]);
        setPaidAmount('');
        setPaymentType('cash');
        setNotes('');
    };

    const handleSavePurchase = async (closeModal: boolean = true) => {
        if (!supplier || orderItems.length === 0) {
            addToast("Please fill supplier and add items", 'error');
            return;
        }

        const purchase: Purchase = {
            orderNumber: orderNumber || `PO-${Date.now()}`,
            supplierName: supplier,
            items: orderItems,
            totalAmount,
            date: new Date(orderDate),
            dueDate: dueDate ? new Date(dueDate) : undefined,
            paymentType: paymentType as any,
            paidAmount: advance,
            notes: notes
        };

        await db.purchases.add(purchase);

        // Update Stock
        for (const orderItem of orderItems) {
            const item = await db.items.get(orderItem.itemId);
            if (item) {
                await db.items.update(item.id!, {
                    stock: item.stock + orderItem.quantity,
                    purchasePrice: orderItem.cost
                });
            }
        }

        resetForm();
        if (closeModal) setIsModalOpen(false);
        addToast("Purchase Order Saved Successfully!", 'success');
        addNotification(`New Purchase Order #${purchase.orderNumber} created`, 'success', (await db.purchases.orderBy('id').last())?.id);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold dark:text-white">Purchase Orders</h1>
                <button
                    onClick={() => { resetForm(); setIsModalOpen(true); }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors"
                >
                    <Plus size={20} /> New Purchase Order
                </button>
            </div>

            {/* Filters */}
            <div className="flex justify-end gap-3 mb-4">
                <div className="flex flex-col">
                    <label className="text-[10px] uppercase font-bold text-slate-400 pl-1">From</label>
                    <input
                        type="date"
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 text-sm shadow-sm"
                    />
                </div>
                <div className="flex flex-col">
                    <label className="text-[10px] uppercase font-bold text-slate-400 pl-1">To</label>
                    <input
                        type="date"
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 text-sm shadow-sm"
                    />
                </div>
            </div>

            {/* List */}
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400">
                        <tr>
                            <th className="p-4 font-medium">Date</th>
                            <th className="p-4 font-medium">Order No</th>
                            <th className="p-4 font-medium">Supplier</th>
                            <th className="p-4 font-medium">Items</th>
                            <th className="p-4 font-medium">Total</th>
                            <th className="p-4 font-medium">Balance</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                        {filteredPurchases?.map((po) => {
                            const paid = po.paidAmount || 0;
                            const balance = po.totalAmount - paid;
                            return (
                                <tr key={po.id || po.orderNumber} className="hover:bg-slate-50 dark:hover:bg-slate-700/50">
                                    <td className="p-4 dark:text-slate-300">{formatDate(po.date)}</td>
                                    <td className="p-4 font-medium dark:text-white">{po.orderNumber}</td>
                                    <td className="p-4 dark:text-white">{po.supplierName}</td>
                                    <td className="p-4 dark:text-slate-300">{po.items.length} Items</td>
                                    <td className="p-4 font-bold text-slate-800 dark:text-white">{formatCurrency(po.totalAmount)}</td>
                                    <td className="p-4">
                                        {balance > 0.01 ?
                                            <span className="text-red-500 font-medium">{formatCurrency(balance)}</span> :
                                            <span className="text-green-500 font-medium">Paid</span>
                                        }
                                    </td>
                                </tr>
                            )
                        })}
                        {filteredPurchases?.length === 0 && (
                            <tr><td colSpan={6} className="p-8 text-center text-slate-500">No purchase orders found for selected date range.</td></tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* Create Modal */}
            <Modal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                title="Purchase Order"
                maxWidth="5xl"
                className="h-[90vh]"
            >
                <div className="flex-1 overflow-hidden flex h-full">
                    {/* Left: Item Selector */}
                    <div className="w-1/3 border-r border-slate-200 dark:border-slate-700 p-4 flex flex-col gap-4 bg-slate-50 dark:bg-slate-800/50">
                        <h3 className="font-semibold text-slate-700 dark:text-slate-200">Add Items</h3>
                        <div className="relative">
                            <Search className="absolute left-3 top-2.5 text-slate-400" size={18} />
                            <input
                                type="text"
                                placeholder="Search inventory..."
                                className="w-full pl-9 p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 dark:text-white"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-2">
                            {filteredInventory?.map(item => (
                                <button
                                    key={item.id}
                                    onClick={() => addToOrder(item)}
                                    className="w-full text-left p-3 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-colors"
                                >
                                    <div className="flex justify-between">
                                        <span className="font-medium dark:text-white">{item.name}</span>
                                        <span className="text-xs bg-slate-100 dark:bg-slate-700 px-2 py-0.5 rounded text-slate-600 dark:text-slate-300">
                                            Stock: {item.stock}
                                        </span>
                                    </div>
                                    <div className="text-xs text-slate-500 mt-1">Cost: {formatCurrency(item.purchasePrice)}</div>
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Right: Form & Details */}
                    <div className="w-2/3 flex flex-col h-full">
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">

                            {/* Top Row: Order No & Date */}
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-medium text-slate-500 mb-1">Order No.</label>
                                    <input
                                        type="text"
                                        className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white font-medium"
                                        value={orderNumber}
                                        onChange={e => setOrderNumber(e.target.value)}
                                        placeholder="Auto-generated"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-medium text-slate-500 mb-1">Date</label>
                                    <input
                                        type="date"
                                        className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                        value={orderDate}
                                        onChange={e => setOrderDate(e.target.value)}
                                    />
                                </div>
                            </div>

                            {/* Party & Due Date */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="col-span-2">
                                    <label className="block text-xs font-medium text-slate-500 mb-1">Party Name*</label>
                                    <input
                                        type="text"
                                        className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white text-lg"
                                        value={supplier}
                                        onChange={e => setSupplier(e.target.value)}
                                        placeholder="Enter Party Name"
                                    />
                                </div>
                                <div className="col-span-2">
                                    <label className="block text-xs font-medium text-slate-500 mb-1">Due Date</label>
                                    <input
                                        type="date"
                                        className="w-full p-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white"
                                        value={dueDate}
                                        onChange={e => setDueDate(e.target.value)}
                                    />
                                </div>
                            </div>

                            {/* Items List */}
                            <div className="space-y-3">
                                <h3 className="font-semibold text-sm text-slate-500 uppercase tracking-wider">Items ({orderItems.length})</h3>
                                <div className="border rounded-lg divide-y dark:border-slate-700 dark:divide-slate-700">
                                    {orderItems.map((item) => (
                                        <div key={item.itemId} className="flex items-center gap-3 p-3 bg-white dark:bg-slate-800">
                                            <div className="flex-1">
                                                <p className="font-medium dark:text-white text-sm">{item.name}</p>
                                            </div>
                                            <div className="w-20">
                                                <input
                                                    type="number"
                                                    className="w-full p-1 text-sm bg-slate-50 dark:bg-slate-900 border rounded text-center dark:text-white"
                                                    value={item.quantity}
                                                    onChange={e => updateOrderItem(item.itemId, 'quantity', parseFloat(e.target.value))}
                                                    placeholder="Qty"
                                                />
                                            </div>
                                            <div className="w-24">
                                                <input
                                                    type="number"
                                                    className="w-full p-1 text-sm bg-slate-50 dark:bg-slate-900 border rounded text-right dark:text-white"
                                                    value={item.cost}
                                                    onChange={e => updateOrderItem(item.itemId, 'cost', parseFloat(e.target.value))}
                                                    placeholder="Cost"
                                                />
                                            </div>
                                            <div className="w-20 text-right font-medium dark:text-white text-sm">
                                                {formatCurrency(item.quantity * item.cost)}
                                            </div>
                                            <button onClick={() => removeOrderItem(item.itemId)} className="text-red-500 hover:text-red-700">
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    ))}
                                    {orderItems.length === 0 && (
                                        <div className="p-4 text-center text-slate-400 text-sm">No items added yet.</div>
                                    )}
                                </div>
                            </div>

                            {/* Financials & Payment */}
                            <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl space-y-4">
                                <div className="flex justify-between items-center text-lg font-bold">
                                    <span className="dark:text-white">Total Amount</span>
                                    <span className="dark:text-white">{formatCurrency(totalAmount)}</span>
                                </div>

                                <div className="grid grid-cols-2 gap-4 items-center">
                                    <label className="text-sm font-medium text-slate-600 dark:text-slate-300">Advance Amt</label>
                                    <input
                                        type="number"
                                        className="p-2 rounded border dark:bg-slate-900 dark:border-slate-600 dark:text-white text-right"
                                        placeholder="0.00"
                                        value={paidAmount}
                                        onChange={e => setPaidAmount(e.target.value)}
                                    />
                                </div>

                                <div className="flex justify-between items-center font-bold text-emerald-600">
                                    <span>Balance Due</span>
                                    <span>{formatCurrency(balanceDue)}</span>
                                </div>
                            </div>

                            <div className="space-y-4 pt-4 border-t dark:border-slate-700">
                                <div className="flex justify-between items-center">
                                    <label className="text-sm font-medium dark:text-slate-300">Payment Type</label>
                                    <select
                                        className="p-2 rounded border dark:bg-slate-900 dark:border-slate-600 dark:text-white"
                                        value={paymentType}
                                        onChange={e => setPaymentType(e.target.value)}
                                    >
                                        <option value="cash">Cash</option>
                                        <option value="card">Card</option>
                                        <option value="upi">UPI/Digital</option>
                                        <option value="credit">Credit</option>
                                    </select>
                                </div>

                                <textarea
                                    className="w-full p-3 rounded-lg border border-slate-300 dark:border-slate-600 bg-transparent dark:text-white text-sm"
                                    rows={2}
                                    placeholder="Description / Notes..."
                                    value={notes}
                                    onChange={e => setNotes(e.target.value)}
                                ></textarea>
                            </div>

                        </div>

                        {/* Footer Actions */}
                        <div className="p-4 border-t border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 flex justify-between gap-4 shrink-0">
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="px-6 py-2.5 rounded-xl font-medium text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800 transition-colors"
                            >
                                Cancel
                            </button>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => handleSavePurchase(false)}
                                    className="px-6 py-2.5 rounded-xl font-medium bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-200 dark:hover:bg-slate-700 transition-colors"
                                >
                                    Save & New
                                </button>
                                <button
                                    onClick={() => handleSavePurchase(true)}
                                    className="px-8 py-2.5 rounded-xl font-bold bg-[#E11D48] text-white hover:bg-[#BE123C] shadow-lg shadow-rose-500/30 transition-all transform active:scale-95 flex items-center gap-2"
                                >
                                    <Save size={18} /> Save
                                </button>
                            </div>
                        </div>

                    </div>
                </div>
            </Modal>
        </div>
    );
};

export default PurchaseOrders;

