import React, { useState } from 'react';
import { Bell } from 'lucide-react';
import { useNotification } from '../../../contexts/NotificationContext'; // Assuming context handles actual logic or we save to LS

const RemindersTab: React.FC = () => {
    // Persist to localStorage
    const [settings, setSettings] = useState(() => {
        const saved = localStorage.getItem('reminderSettings');
        return saved ? JSON.parse(saved) : {
            lowStock: true,
            paymentDue: true
        };
    });

    const { addToast } = useNotification();

    const toggleSetting = (key: 'lowStock' | 'paymentDue') => {
        const newSettings = { ...settings, [key]: !settings[key] };
        setSettings(newSettings);
        localStorage.setItem('reminderSettings', JSON.stringify(newSettings));
        addToast(`${key === 'lowStock' ? 'Low Stock' : 'Payment Due'} Notifications ${newSettings[key] ? 'Enabled' : 'Disabled'}`, 'success');
    };

    const Toggle = ({ enabled, onChange }: { enabled: boolean; onChange: () => void }) => (
        <button
            onClick={onChange}
            className={`w-14 h-8 rounded-full transition-colors relative ${enabled ? 'bg-blue-600' : 'bg-slate-300 dark:bg-slate-600'}`}
        >
            <span className={`absolute top-1 left-1 w-6 h-6 bg-white rounded-full shadow-md transition-transform ${enabled ? 'translate-x-6' : 'translate-x-0'}`} />
        </button>
    );

    return (
        <div className="space-y-6">
            <h2 className="text-xl font-bold dark:text-white flex items-center gap-2">
                <Bell className="text-blue-500" /> Reminders Configuration
            </h2>

            <div className="space-y-4">
                {/* Low Stock Toggle */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center justify-between">
                    <div>
                        <h3 className="font-semibold text-slate-800 dark:text-white">Low Stock Alerts</h3>
                        <p className="text-sm text-slate-500 mt-1">
                            Get notified when items fall below their minimum stock level.
                        </p>
                    </div>
                    <Toggle enabled={settings.lowStock} onChange={() => toggleSetting('lowStock')} />
                </div>

                {/* Payment Due Toggle */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center justify-between">
                    <div>
                        <h3 className="font-semibold text-slate-800 dark:text-white">Customer Due Dates</h3>
                        <p className="text-sm text-slate-500 mt-1">
                            Receive reminders for customer invoices that are overdue.
                        </p>
                    </div>
                    <Toggle enabled={settings.paymentDue} onChange={() => toggleSetting('paymentDue')} />
                </div>
            </div>
        </div>
    );
};

export default RemindersTab;

