import React, { useState, useEffect } from 'react';
import { Plus, User as UserIcon, Trash2, Edit } from 'lucide-react';
import { db, type User } from '../../services/db';
import { useAuth } from '../../contexts/AuthContext';
import { useNotification } from '../../contexts/NotificationContext';
import UserForm from './UserForm';

const UserList: React.FC = () => {
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [editingUser, setEditingUser] = useState<User | undefined>(undefined);
    const { user: currentUser } = useAuth();
    const { addToast } = useNotification();

    const fetchUsers = async () => {
        try {
            const data = await db.users.toArray();
            setUsers(data);
        } catch (error) {
            console.error(error);
            addToast('Failed to load users', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchUsers();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleDelete = async (id: number) => {
        if (!confirm('Are you sure you want to delete this user?')) return;
        try {
            await db.users.delete(id);
            addToast('User deleted successfully', 'success');
            fetchUsers();
        } catch (error) {
            addToast('Failed to delete user', 'error');
        }
    };

    const handleEdit = (user: User) => {
        setEditingUser(user);
        setShowForm(true);
    };

    const handleFormClose = () => {
        setShowForm(false);
        setEditingUser(undefined);
        fetchUsers();
    };

    if (loading) return <div className="p-6">Loading users...</div>;

    return (
        <div className="p-6 space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold flex items-center gap-2">
                    <UserIcon className="w-8 h-8 text-indigo-600" />
                    User Management
                </h1>
                <button
                    onClick={() => setShowForm(true)}
                    className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700"
                >
                    <Plus className="w-4 h-4" />
                    Add User
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-lg border border-indigo-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-indigo-50 border-b border-indigo-100">
                        <tr>
                            <th className="p-4 font-semibold text-indigo-900">Username</th>
                            <th className="p-4 font-semibold text-indigo-900">Name</th>
                            <th className="p-4 font-semibold text-indigo-900">Role</th>
                            <th className="p-4 font-semibold text-indigo-900 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-indigo-50">
                        {users.map((userItem) => (
                            <tr key={userItem.id} className="hover:bg-indigo-50/50 transition-colors">
                                <td className="p-4 font-medium text-gray-900">{userItem.username}</td>
                                <td className="p-4 text-gray-600">{userItem.name}</td>
                                <td className="p-4">
                                    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${userItem.role === 'admin'
                                        ? 'bg-purple-100 text-purple-700'
                                        : 'bg-blue-100 text-blue-700'
                                        }`}>
                                        {userItem.role}
                                    </span>
                                </td>
                                <td className="p-4 text-right space-x-2">
                                    <button
                                        onClick={() => handleEdit(userItem)}
                                        className="text-gray-400 hover:text-indigo-600 transition-colors"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    {currentUser?.username !== userItem.username && (
                                        <button
                                            onClick={() => userItem.id && handleDelete(userItem.id)}
                                            className="text-gray-400 hover:text-red-600 transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Form Modal */}
            {showForm && (
                <UserForm
                    user={editingUser}
                    onClose={handleFormClose}
                    onSave={fetchUsers}
                />
            )}
        </div>
    );
};

export default UserList;

import { jsPDF } from 'jspdf';
import { format } from 'date-fns';
import { generateZatcaQR, formatZatcaDate } from './zatca';
import type { Invoice } from './db';
// import { generateThermalInvoice } from './thermalPrinter';
import 'jspdf-autotable';

interface BusinessDetails {
    name: string;
    address: string;
    phone: string;
    email: string;
    gstin?: string; // VAT/GST/Tax ID
    logoUrl?: string; // Base64
    country?: string;
    taxName?: string; // 'VAT' | 'GST'
    taxRate?: number; // Added for passing rate
    crNo?: string; // Commercial Registration
    pincode?: string;
}

// Printer Config Interface
interface PrinterConfig {
    printerType: 'regular' | 'thermal';
    pageSize: 'a4' | 'letter' | '80mm' | '58mm' | '100mm' | 'custom';
    orientation: 'portrait' | 'landscape';
    textSize: 'small' | 'medium' | 'large';
    printCompanyName: boolean;
    headerTextSize: 'small' | 'medium' | 'large';
    extraLines: number;
    copies: number;
    nativePrinting: boolean;
    textStyling: boolean;
    autoCut: boolean;
    openDrawer: boolean;
    printLanguage?: 'english' | 'bilingual';
    showTerms?: boolean;
    termsContent?: string;
    enableSilentPrint?: boolean;
    selectedPrinter?: string;
}

// --- HTML GENERATOR ---
export const getInvoiceHTML = async (invoice: Invoice, business: BusinessDetails): Promise<string | null> => {
    // 1. Load Settings
    const savedConfig = localStorage.getItem('printerConfig');
    const config: PrinterConfig = savedConfig ? JSON.parse(savedConfig) : {
        printerType: 'regular',
        pageSize: 'a4',
        orientation: 'portrait',
        textSize: 'medium',
        printCompanyName: true,
        headerTextSize: 'large',
        extraLines: 0,
        copies: 1,
        nativePrinting: false,
        textStyling: true,
        autoCut: false,
        openDrawer: false
    };

    // Parse App Settings for Formatting
    const savedAppSettings = localStorage.getItem('appSettings');
    const appSettings = savedAppSettings ? JSON.parse(savedAppSettings) : { currency: '$', decimals: 2, dateFormat: 'dd/MM/yyyy' };

    // Helper Formatters
    const formatCurrency = (amount: number) => appSettings.currency + Number(amount).toFixed(appSettings.decimals);


    // If Thermal, we actually usually delegate, but if we need HTML for download, we generate it.
    // Ideally we should have a thermal-specific HTML generator, but for now we'll use a standard one
    // or return null if we want to force native thermal handling (which we might not want for download).

    const isBilingual = config.printLanguage === 'bilingual';
    const t = (en: string, ar: string) => isBilingual ? `<div class="bilingual-text"><span class="en">${en}</span><span class="ar">${ar}</span></div>` : en;
    const tLabel = (en: string, ar: string) => isBilingual ? `${en} / <span class="ar">${ar}</span>` : en;

    const appliedTaxRate = invoice.taxRate ?? (business.taxRate || 15);

    // Calculations
    let displayBase = invoice.subTotal;
    let displayTax = invoice.taxAmount;
    let displayNet = invoice.grandTotal;

    // Recalculate base if tax implies inclusive/exclusive logic not captured in invoice object
    // For now assuming invoice object is correct source of truth

    const totalQty = invoice.items.reduce((sum, item) => sum + item.quantity, 0);

    // QR Code
    let qrImg = '';
    if (business.gstin) {
        qrImg = await generateZatcaQR(
            business.name,
            business.gstin,
            formatZatcaDate(new Date(invoice.createdAt)),
            invoice.grandTotal.toFixed(2),
            invoice.taxAmount.toFixed(2)
        );
    }

    return `
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="UTF-8">
        <style>
            @media print {
                @page { size: ${config.pageSize === 'letter' ? 'Letter' : 'A4'} ${config.orientation === 'landscape' ? 'landscape' : 'portrait'}; margin: 0; }
                body { margin: 20mm; -webkit-print-color-adjust: exact; }
            }
            body { 
                font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                color: #333;
                background: #fff;
                padding: 20px;
            }
            .ar { font-family: 'Tahoma', sans-serif; direction: rtl; }
            .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 30px; border-bottom: 2px solid #eee; padding-bottom: 20px; }
            .logo-section img { max-height: 80px; max-width: 200px; }
            .company-info { text-align: right; }
            .company-name { font-size: 24px; font-weight: bold; color: #2563eb; margin-bottom: 5px; }
            .meta-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 30px; }
            .meta-box { border: 1px solid #eee; border-radius: 8px; padding: 15px; }
            .meta-title { font-size: 12px; text-transform: uppercase; color: #000; margin-bottom: 10px; font-weight: 700; letter-spacing: 0.5px; }
            .meta-row { display: flex; justify-content: space-between; margin-bottom: 5px; font-size: 14px; color: #000; }
            .invoice-table { width: 100%; border-collapse: collapse; margin-bottom: 30px; }
            .invoice-table th { background: #f8fafc; text-align: left; padding: 12px; font-size: 12px; font-weight: 700; text-transform: uppercase; border-bottom: 2px solid #333; color: #000; }
