// --- PDF GENERATOR (jsPDF) ---
export const generateInvoicePDF = async (invoice: Invoice, businessDetails: BusinessDetails) => {
    // Read App Settings
    const savedSettings = localStorage.getItem('appSettings');
    const settings = savedSettings ? JSON.parse(savedSettings) : { currency: '$', decimals: 2, dateFormat: 'dd/MM/yyyy' };

    // Helper to format currency
    const formatCurrency = (amount: number) => {
        return settings.currency + Number(amount).toFixed(settings.decimals);
    };

    // Helper to format date
    const formatDate = (dateString: string | Date) => {
        if (!dateString) return '';
        const d = new Date(dateString);
        if (isNaN(d.getTime())) return '';
        const day = String(d.getDate()).padStart(2, '0');
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const year = d.getFullYear();
        if (settings.dateFormat === 'MM/dd/yyyy') return `${month}/${day}/${year}`;
        if (settings.dateFormat === 'yyyy-MM-dd') return `${year}-${month}-${day}`;
        return `${day}/${month}/${year}`;
    };

    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    let yPos = 20;

    // --- Header ---
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("TAX INVOICE", pageWidth / 2, yPos, { align: "center" });
    yPos += 15;

    // --- Business Details ---
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text(businessDetails?.name || "My Shop", 15, yPos);

    // Invoice Info (Right Aligned)
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    const dateText = `Date: ${formatDate(invoice.createdAt)} ${new Date(invoice.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    doc.text(dateText, pageWidth - 15, yPos, { align: "right" });
    yPos += 6;

    doc.text(businessDetails?.address || "Address Line 1", 15, yPos);
    doc.text(`Invoice #: ${invoice.invoiceNumber}`, pageWidth - 15, yPos, { align: "right" });
    yPos += 6;

    if (businessDetails?.phone) {
        doc.text(`Phone: ${businessDetails.phone}`, 15, yPos);
    }
    doc.text(`Customer: ${invoice.customerName}`, pageWidth - 15, yPos, { align: "right" });

    yPos += 15;

    // --- Table ---
    const tableColumn = ["Item", "Qty", "Price", "Total"];
    const tableRows: any[] = [];

    invoice.items.forEach((item) => {
        const itemData = [
            item.name,
            item.quantity.toString(),
            formatCurrency(item.price),
            formatCurrency(item.price * item.quantity),
        ];
        tableRows.push(itemData);
    });

    (doc as any).autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: yPos,
        theme: 'grid',
        headStyles: { fillColor: [66, 66, 66], textColor: 255 },
        styles: { fontSize: 10, cellPadding: 3 },
        margin: { top: 10 },
    });

    // --- Totals ---
    // @ts-ignore
    let finalY = doc.lastAutoTable.finalY + 10;
    const rightMargin = pageWidth - 15;

    doc.setFontSize(11);
    doc.text(`Subtotal: ${formatCurrency(invoice.subTotal)}`, rightMargin, finalY, { align: "right" });
    finalY += 7;

    if (invoice.taxAmount > 0) {
        doc.text(`Tax: ${formatCurrency(invoice.taxAmount)}`, rightMargin, finalY, { align: "right" });
        finalY += 7;
    }

    if (invoice.discountAmount > 0) {
        doc.text(`Discount: -${formatCurrency(invoice.discountAmount)}`, rightMargin, finalY, { align: "right" });
        finalY += 7;
    }

    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text(`Grand Total: ${formatCurrency(invoice.grandTotal)}`, rightMargin, finalY, { align: "right" });
    finalY += 15;

    // --- Footer ---
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text("Thank you for your business!", pageWidth / 2, finalY, { align: "center" });

    // --- Silent Print (Electron) ---
    const printConfig = JSON.parse(localStorage.getItem('printerConfig') || '{}');
    if (printConfig.enableSilentPrint && printConfig.selectedPrinter) {
        // Get the raw PDF array buffer
        const pdfOutput = doc.output('arraybuffer');

        // Send to Electron
        if (window.electron && window.electron.printThermal) {
            await window.electron.printThermal(pdfOutput, {
                printerName: printConfig.selectedPrinter,
                silent: true
            });
        }
        return;
    }

    // Default Browser Print
    doc.autoPrint();
    window.open(doc.output('bloburl'), '_blank');
};

// --- DOWNLOAD FUNCTION (Electron) ---
export const downloadInvoicePDF = async (invoice: Invoice, business: BusinessDetails) => {
    const html = await getInvoiceHTML(invoice, business);
    if (!html) return false;

    if (window.electron && window.electron.downloadPDF) {
        return await window.electron.downloadPDF(html, `Invoice-${invoice.invoiceNumber}.pdf`);
    } else {
        alert("Download only supported in Desktop App mode.");
        return false;
    }
};
